import{bQ as a,aL as o,u as r,G as l}from"./chunks/framework.DaEK0KQB.js";const g=JSON.parse('{"title":"隐私政策","description":"kcshen.cn 的隐私政策，说明 Cookie、Google AdSense 广告、访问统计与评论信息如何被使用。","frontmatter":{"title":"隐私政策","description":"kcshen.cn 的隐私政策，说明 Cookie、Google AdSense 广告、访问统计与评论信息如何被使用。","date":"2026-11-03T12:00:00.000Z","permalink":"/privacy","article":false,"sidebar":false,"categories":[]},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":1793847465000}'),t={name:"privacy.md"};function i(n,e,s,c,h,d){return o(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p>本政策说明个人技术博客 <a href="https://kcshen.cn" target="_blank" rel="noreferrer">kcshen.cn</a>（下称「本站」）如何使用 Cookie、本地存储以及第三方服务。运营者：KC（GitHub：<a href="https://github.com/akcshen" target="_blank" rel="noreferrer">akcshen</a>）。</p><p>生效日期：2026 年 11 月 3 日。</p><h2 id="本站收集什么" tabindex="-1">本站收集什么 <a class="header-anchor" href="#本站收集什么" aria-label="Permalink to &quot;本站收集什么&quot;">​</a></h2><p>本站是静态博客，阅读文章不需要注册。你主动留下的信息主要来自评论和邮件：</p><ul><li><strong>评论（Waline）</strong>：昵称、邮箱，以及你写下的评论。评论服务位于 <code>https://waline.kcshen.cn</code>。邮箱用于显示头像和回复通知，不会出售给他人。</li><li><strong>邮件</strong>：关于页公布的 <a href="mailto:qunfuns@gmail.com" target="_blank" rel="noreferrer">qunfuns@gmail.com</a>，以及页脚社交链接中的 <a href="mailto:kcqingfeng@gmail.com" target="_blank" rel="noreferrer">kcqingfeng@gmail.com</a>。来信只用于回复你。</li></ul><h2 id="cookie-与本地存储" tabindex="-1">Cookie 与本地存储 <a class="header-anchor" href="#cookie-与本地存储" aria-label="Permalink to &quot;Cookie 与本地存储&quot;">​</a></h2><p>本站和接入的第三方可能使用 Cookie、像素或浏览器本地存储，用于：</p><ul><li>记住深色或浅色主题等界面偏好</li><li>维持评论登录状态</li><li>统计访问（百度统计）</li><li>投放、限制展示次数并衡量广告（Google AdSense）</li></ul><p>你可以在浏览器里查看、阻止或删除 Cookie。阻止之后，主题记忆、评论登录或广告相关功能可能不可用，文章正文仍可阅读。</p><h2 id="google-adsense-与个性化广告" tabindex="-1">Google AdSense 与个性化广告 <a class="header-anchor" href="#google-adsense-与个性化广告" aria-label="Permalink to &quot;Google AdSense 与个性化广告&quot;">​</a></h2><p>本站使用 Google AdSense 展示广告，发布商编号为 <code>ca-pub-7321685207191636</code>。Google 及其广告合作伙伴可能根据你对本站和其他网站的访问，使用 Cookie 投放广告、限制同一广告的展示次数，并统计广告是否被看到。其中可能包含<strong>个性化广告</strong>。</p><p>Google 如何使用从合作网站收集的数据，见 <a href="https://policies.google.com/technologies/ads" target="_blank" rel="noreferrer">广告与 Cookie 技术说明</a>。</p><p>你可以关闭个性化广告：</p><ul><li>打开 <a href="https://adssettings.google.com/" target="_blank" rel="noreferrer">Google 广告设置</a>（也可从 <a href="https://myadcenter.google.com/" target="_blank" rel="noreferrer">我的广告中心</a> 进入），关闭个性化广告</li><li>了解行业退出选项：<a href="https://optout.aboutads.info/" target="_blank" rel="noreferrer">optout.aboutads.info</a></li><li>在浏览器中禁止第三方 Cookie</li></ul><p>关闭个性化广告后，你仍可能看到广告，只是这些广告不再依据兴趣档案挑选。</p><h2 id="访问统计" tabindex="-1">访问统计 <a class="header-anchor" href="#访问统计" aria-label="Permalink to &quot;访问统计&quot;">​</a></h2><p>本站使用百度统计了解哪些文章有人阅读（统计 ID <code>38887d8123fcb847f9f51006e70b9898</code>）。它可能用 Cookie 记录大致来源、页面和设备类型。这些数据用于改进内容，不用于出售个人信息。</p><h2 id="第三方资源" tabindex="-1">第三方资源 <a class="header-anchor" href="#第三方资源" aria-label="Permalink to &quot;第三方资源&quot;">​</a></h2><p>文章页可能加载 Waline 评论脚本与样式（jsDelivr）、图标字体，以及 Google 广告脚本。这些服务按其各自的隐私政策处理数据。</p><h2 id="不会做的事" tabindex="-1">不会做的事 <a class="header-anchor" href="#不会做的事" aria-label="Permalink to &quot;不会做的事&quot;">​</a></h2><ul><li>不出售个人信息</li><li>不把评论邮箱放进本站以外的营销名单</li><li>本站面向普通读者，不以 13 岁以下儿童为对象，也不会故意收集儿童信息</li></ul><h2 id="政策更新与联系" tabindex="-1">政策更新与联系 <a class="header-anchor" href="#政策更新与联系" aria-label="Permalink to &quot;政策更新与联系&quot;">​</a></h2><p>第三方服务或本站做法变化时，会更新本页的生效日期。继续使用本站，即表示你了解更新后的说明。</p><p>隐私相关问题请发邮件至 <a href="mailto:qunfuns@gmail.com" target="_blank" rel="noreferrer">qunfuns@gmail.com</a>，或通过 <a href="https://github.com/akcshen" target="_blank" rel="noreferrer">GitHub akcshen</a> 联系。</p>',25)])])}const f=a(t,[["render",i]]);export{g as __pageData,f as default};
